manifest=json.loads((R/'assets-manifest.json').read_text(encoding='utf-8'))
releases=manifest['releases']
def esc(s):return html.escape(s,quote=True)
cards=[];artists=[]
for i,r in enumerate(releases):
    cards.append(f'''<article class="release-card" data-search="{esc(r['artist']+' '+r['title'])}"><button class="cover-button" data-release="{i}" aria-label="Explore {esc(r['title'])} by {esc(r['artist'])}"><img src="{r['file']}" width="600" height="600" loading="lazy" alt="{esc(r['title'])} — original cover artwork"><span class="cover-index">{i+1:02d} / SELECTED</span><span class="cover-action" aria-hidden="true">↗</span></button><div class="release-meta"><div><h3>{esc(r['artist'])}</h3><p>{esc(r['title'])}</p></div><button class="release-open" data-release="{i}" aria-label="Open {esc(r['title'])}">↗</button></div></article>''')
for i,r in enumerate(sorted(releases,key=lambda a:a['artist'])):
    artists.append(f'''<a class="artist-row" href="{r['album_url']}" target="_blank" rel="noopener"><span class="number">{i+1:02d}</span><strong>{esc(r['artist'])}</strong><span class="artist-release">{esc(r['title'])}</span><span class="arrow" aria-hidden="true">↗</span></a>''')
